package br.com.lealinfo.vidraceiro;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.*;
/** Typed, dimension-driven glass surfaces. Strokes identify the model, never fabrication thickness. */
final class ProjectDrawing extends View {
 double widthMm,heightMm,depthMm;boolean threeD=true,dimensions=true;float yaw=-25,pitch=18,zoom=1,lastX,lastY;int panels=1;String service="Vidro fixo";final Paint paint=new Paint(3);final ScaleGestureDetector pinch;
 ProjectDrawing(Context c,double w,double h,double d,int count){super(c);widthMm=w;heightMm=h;depthMm=d;panels=count;setContentDescription("Representação do projeto em 2D e 3D");pinch=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector s){setZoom(zoom*s.getScaleFactor());return true;}});}
 void setZoom(float z){zoom=Math.max(.55f,Math.min(2.5f,z));invalidate();}
 void reset(){yaw=-25;pitch=18;zoom=1;invalidate();}
 String kind(){String s=service.toLowerCase(new Locale("pt","BR"));if(s.contains("box"))return "BOX";if(s.contains("janela")||s.contains("esquadria"))return "JANELA";if(s.contains("porta"))return "PORTA";if(s.contains("espelho"))return "ESPELHO";if(s.contains("guarda"))return "GUARDA-CORPO";if(s.contains("divis"))return "DIVISÓRIA";if(s.contains("fechamento"))return "FECHAMENTO";return "VIDRO FIXO";}
 int surfaceCount(){return kind().equals("BOX")&&depthMm>0?2:1;}
 float[] project(double x,double y,double z,double scale){double cy=Math.cos(Math.toRadians(threeD?yaw:0)),sy=Math.sin(Math.toRadians(threeD?yaw:0)),cp=Math.cos(Math.toRadians(threeD?pitch:0)),sp=Math.sin(Math.toRadians(threeD?pitch:0));double xx=x*cy+z*sy,zz=-x*sy+z*cy;return new float[]{(float)(getWidth()*.5+xx*scale),(float)(getHeight()*.56-(y*cp-zz*sp)*scale),(float)(y*sp+zz*cp)};}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(9,22,39));if(widthMm<=0||heightMm<=0)return;float density=getResources().getDisplayMetrics().density;double max=Math.max(widthMm,Math.max(heightMm,depthMm)),w=widthMm/max,h=heightMm/max,d=depthMm/max;double scale=Math.min((getWidth()-44*density)/Math.max(w+d*.5,.1),(getHeight()-100*density)/Math.max(h+d*.3,.1))*.72*zoom;ArrayList<float[][]> faces=new ArrayList<>();float[][] front={project(-w/2,-h/2,-d/2,scale),project(w/2,-h/2,-d/2,scale),project(w/2,h/2,-d/2,scale),project(-w/2,h/2,-d/2,scale)};faces.add(front);if(surfaceCount()==2&&threeD)faces.add(new float[][]{project(-w/2,-h/2,d/2,scale),front[0],front[3],project(-w/2,h/2,d/2,scale)});faces.sort((a,b)->Float.compare(depth(a),depth(b)));
 // Floor cues provide orientation, not dimensions or additional project components.
 if(threeD){paint.setStrokeWidth(density);paint.setColor(0x223eb5d2);for(int i=-2;i<=2;i++){float[] a=project(i*.25,-h/2,-.65,scale),b=project(i*.25,-h/2,.65,scale);c.drawLine(a[0],a[1],b[0],b[1],paint);float[] e=project(-.65,-h/2,i*.25,scale),f=project(.65,-h/2,i*.25,scale);c.drawLine(e[0],e[1],f[0],f[1],paint);}}
 for(float[][] face:faces)drawGlass(c,face,density);paint.setStyle(Paint.Style.FILL);paint.setShader(null);paint.setColor(0xffd2ebfa);paint.setTextSize(13*getResources().getDisplayMetrics().scaledDensity);if(dimensions){c.drawText(fmt(widthMm)+" × "+fmt(heightMm)+" mm",16*density,23*density,paint);if(depthMm>0)c.drawText("Profundidade: "+fmt(depthMm)+" mm",16*density,44*density,paint);}paint.setTextSize(11*getResources().getDisplayMetrics().scaledDensity);c.drawText(kind()+(kind().equals("BOX")?(depthMm>0?" • frente + retorno":" • frontal; retorno não informado"):""),16*density,getHeight()-14*density,paint);}
 void drawGlass(Canvas c,float[][] f,float density){Path path=new Path();path.moveTo(f[0][0],f[0][1]);for(int i=1;i<4;i++)path.lineTo(f[i][0],f[i][1]);path.close();boolean mirror=kind().equals("ESPELHO");paint.setStyle(Paint.Style.FILL);paint.setShader(new LinearGradient(f[3][0],f[3][1],f[1][0],f[1][1],mirror?new int[]{0xff52748b,0xffc7e3eb,0xff345369}:new int[]{0xc82d829d,0x7863b0c8,0xc8123c55},null,Shader.TileMode.CLAMP));c.drawPath(path,paint);paint.setShader(null);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth((kind().equals("JANELA")||kind().equals("PORTA")?3:1.8f)*density);paint.setColor(0xff9beaff);c.drawPath(path,paint);
 // Inset outlines are symbolic screen strokes, not assumed profiles or clearances.
 if(kind().equals("JANELA")||kind().equals("PORTA")){Path outline=new Path();for(int i=0;i<4;i++){float x=(i==0||i==3)?.025f:.975f,y=i<2?.025f:.975f;float[] at=at(f,x,y);if(i==0)outline.moveTo(at[0],at[1]);else outline.lineTo(at[0],at[1]);}outline.close();paint.setStrokeWidth(density);c.drawPath(outline,paint);}
 for(int i=1;i<panels;i++){float t=i/(float)panels;float[] a=at(f,t,0),b=at(f,t,1);paint.setStrokeWidth(1.5f*density);c.drawLine(a[0],a[1],b[0],b[1],paint);}
 c.save();c.clipPath(path);paint.setColor(0x426ee5ff);paint.setStrokeWidth(9*density);float[] a=at(f,.10f,0),b=at(f,.6f,1);c.drawLine(a[0],a[1],b[0],b[1],paint);paint.setColor(0x36ffffff);paint.setStrokeWidth(2*density);a=at(f,.2f,0);b=at(f,.7f,1);c.drawLine(a[0],a[1],b[0],b[1],paint);c.restore();}
 float[] at(float[][] f,float x,float y){return new float[]{f[0][0]+(f[1][0]-f[0][0])*x+(f[3][0]-f[0][0])*y,f[0][1]+(f[1][1]-f[0][1])*x+(f[3][1]-f[0][1])*y};}
 private String fmt(double d){return java.math.BigDecimal.valueOf(d).stripTrailingZeros().toPlainString().replace('.',',');}private float depth(float[][] f){float d=0;for(float[] p:f)d+=p[2];return d;}
 @Override public boolean onTouchEvent(MotionEvent e){pinch.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!pinch.isInProgress()&&e.getPointerCount()==1){yaw=Math.max(-65,Math.min(65,yaw+(e.getX()-lastX)*.5f));pitch=Math.max(-55,Math.min(55,pitch-(e.getY()-lastY)*.5f));lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);performClick();}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
